insert into businesses(name,category,city,address,phone,website,description,status,verified,claimed,rating,review_count,source,source_url,verification_source,verified_at) values('Irish Heating and Air Conditioning LLC','Home Services','Tracy',null,'(209) 257-3999','https://www.irishheatandair.com/','Advertises furnace repair, installation and maintenance alongside air conditioning and commercial HVAC. Its official service pages explicitly name Mountain House, Tracy, Lathrop and Manteca. The Tracy contact number is shown here; a walk-in office is not established. Confirm job type, quote, current service coverage and appointment availability directly.','approved',true,false,null,0,'editorial_first_party','https://www.irishheatandair.com/heating-ac-repairs-lathrop/','first_party_website_desk_check',now()) returning id into bid;
