insert into directory_private.listing_corrections(business_id,previous_values,applied_values,reason,source_reference) values(bid,'{}'::jsonb,'{"name": "Irish Heating and Air Conditioning LLC", "city": "Tracy", "phone": "(209) 257-3999", "website": "https://www.irishheatandair.com/", "source_url": "https://www.irishheatandair.com/heating-ac-repairs-lathrop/", "description": "Advertises furnace repair, installation and maintenance alongside air conditioning and commercial HVAC. Its official service pages explicitly name Mountain House, Tracy, Lathrop and Manteca. The Tracy contact number is shown here; a walk-in office is not established. Confirm job type, quote, current service coverage and appointment availability directly."}'::jsonb,'Priority heating service coverage expansion','https://www.irishheatandair.com/heating-ac-repairs-lathrop/');end $curate$;
